<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/auth.php';
$user=require_role('donor'); $pdo=db(); $errors=[];
if(is_post()){
    verify_csrf(); $action=$_POST['action']??'';
    if($action==='add'){
        $category=$_POST['category']??''; $size=$_POST['size_label']??''; $season=$_POST['season']??'All season'; $quantity=filter_var($_POST['quantity']??0,FILTER_VALIDATE_INT,['options'=>['min_range'=>1,'max_range'=>500]]);
        if(!in_array($category,clothing_categories(),true)||!in_array($size,clothing_sizes(),true)||!in_array($season,['All season','Spring','Summer','Autumn','Winter'],true)||!$quantity)$errors[]='Add a valid category, size, season and quantity.';
        if(!$errors){$stmt=$pdo->prepare('INSERT INTO donor_inventory (user_id,category,size_label,season,quantity) VALUES (?,?,?,?,?)');$stmt->execute([$user['id'],$category,$size,$season,$quantity]);flash('success','Your item was added. Matching needs are below.');redirect('donor/matcher.php');}
    } elseif($action==='delete') { $stmt=$pdo->prepare('DELETE FROM donor_inventory WHERE id=? AND user_id=?');$stmt->execute([(int)($_POST['item_id']??0),$user['id']]);flash('success','Item removed from your matcher.');redirect('donor/matcher.php'); }
}
$itemsStmt=$pdo->prepare('SELECT * FROM donor_inventory WHERE user_id=? ORDER BY created_at DESC');$itemsStmt->execute([$user['id']]);$items=$itemsStmt->fetchAll();$matches=[];
if($items){$matchStmt=$pdo->prepare("SELECT cr.id,cr.title,cr.season,cr.urgency,cr.location,c.organization_name,rr.category,rr.size_label,rr.quantity_needed,
COALESCE((SELECT SUM(di.quantity) FROM donation_items di JOIN donation_pledges dp ON dp.id=di.pledge_id WHERE di.request_requirement_id=rr.id AND dp.status='received'),0) received
FROM clothing_requests cr JOIN charities c ON c.id=cr.charity_id JOIN request_requirements rr ON rr.request_id=cr.id
WHERE cr.status='active' AND rr.category=? AND rr.size_label=? AND (cr.season='All season' OR ?='All season' OR cr.season=?)");
 foreach($items as $item){$matchStmt->execute([$item['category'],$item['size_label'],$item['season'],$item['season']]);foreach($matchStmt->fetchAll() as $row){$remaining=max(0,(int)$row['quantity_needed']-(int)$row['received']);if(!$remaining)continue;$seasonScore=($row['season']==='All season'||$item['season']==='All season')?8:10;$urgencyScore=['urgent'=>10,'high'=>7,'normal'=>4,'low'=>2][$row['urgency']]??0;$row['score']=min(100,65+15+$seasonScore+$urgencyScore);$row['available_quantity']=$item['quantity'];$matches[]=$row;}}
 usort($matches,fn($a,$b)=>$b['score']<=>$a['score'] ?: ['urgent'=>4,'high'=>3,'normal'=>2,'low'=>1][$b['urgency']]<=>['urgent'=>4,'high'=>3,'normal'=>2,'low'=>1][$a['urgency']]);
}
$pageTitle='Smart donation matcher';require __DIR__ . '/../includes/header.php'; ?>
<section class="dashboard"><div class="shell"><div class="subnav"><a href="<?=e(url('donor/dashboard.php'))?>">Dashboard</a><a class="is-active" href="<?=e(url('donor/matcher.php'))?>">Smart matcher</a><a href="<?=e(url('donor/passport.php'))?>">Passport</a><a href="<?=e(url('donor/appointments.php'))?>">Appointments</a><a href="<?=e(url('donor/achievements.php'))?>">Achievements</a><a href="<?=e(url('donor/leaderboard.php'))?>">Leaderboard</a></div><div class="welcome-row"><div><span class="eyebrow">Real matching, no pretend AI</span><h1>Match your clothes to a need.</h1><p>Tell us exactly what you have. Giftly matches category, size and season, then gives urgent requests a real priority boost.</p></div></div>
<div class="layout-two"><div class="panel"><div class="panel-heading"><h2>Add clothing you have</h2><span class="chip chip-sun">Your private matcher list</span></div><?php if($errors):?><div class="flash flash-error"><span><?=e(implode(' ',$errors))?></span></div><?php endif;?><form method="post" class="form-grid" data-loading><?=csrf_field()?><input type="hidden" name="action" value="add"><div class="field"><label>Category</label><select class="select" name="category" required><option value="">Choose</option><?php foreach(clothing_categories() as $v):?><option value="<?=e($v)?>"><?=e($v)?></option><?php endforeach;?></select></div><div class="field"><label>Size</label><select class="select" name="size_label" required><option value="">Choose</option><?php foreach(clothing_sizes() as $v):?><option value="<?=e($v)?>"><?=e($v)?></option><?php endforeach;?></select></div><div class="field"><label>Season</label><select class="select" name="season"><?php foreach(['All season','Spring','Summer','Autumn','Winter'] as $v):?><option value="<?=e($v)?>"><?=e($v)?></option><?php endforeach;?></select></div><div class="field"><label>Quantity</label><input class="input" type="number" min="1" max="500" name="quantity" value="1" required></div><div class="field field-full"><button class="button" type="submit">Find matching needs →</button></div></form><hr style="border:0;border-top:1px solid var(--border);margin:23px 0"><h2 style="margin-bottom:12px">Your matcher list</h2><?php if(!$items):?><div class="empty"><span class="empty-icon">⌘</span>Add an item to unlock genuine database matches.</div><?php else:foreach($items as $item):?><div class="requirement-row" style="display:flex;justify-content:space-between;gap:12px;align-items:center"><div><strong><?=e($item['quantity'])?> × <?=e($item['category'])?></strong><p><?=e($item['size_label'])?> · <?=e($item['season'])?></p></div><form method="post" data-loading data-confirm="Remove this item from your matcher list?"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="item_id" value="<?=$item['id']?>"><button class="button button-danger button-small">Remove</button></form></div><?php endforeach;endif;?></div><aside class="panel"><div class="panel-heading"><h2>How match score works</h2></div><p class="section-description">Exact category and size are essential. Season alignment adds relevance, then urgency determines how high a compatible need appears.</p><div class="callout"><strong>Why the score is useful</strong><br>It is calculated from your saved clothing and real requirement records—never generated from fake AI.</div></aside></div>
<div class="panel" style="margin-top:22px"><div class="panel-heading"><h2><?=count($matches)?> matching <?=count($matches)===1?'need':'needs'?></h2><span class="muted">Urgent requests rise to the top</span></div><?php if(!$matches):?><div class="empty"><span class="empty-icon">✦</span>No exact active matches yet. Try a different size, category, or browse all needs.</div><?php else:?><div class="request-grid"><?php foreach(array_slice($matches,0,12) as $match):?><article class="request-card"><div class="card-top"><span class="status <?=e(status_class($match['urgency']==='urgent'?'pending':'active'))?>"><?=e($match['urgency'])?></span><strong style="color:var(--coral)"><?=$match['score']?>% match</strong></div><h3><?=e($match['title'])?></h3><p><?=e($match['organization_name'])?> · <?=e($match['location'])?></p><div class="progress"><span style="width:<?=$match['score']?>%"></span></div><div class="progress-info"><span><?=e($match['category'])?> · <?=e($match['size_label'])?></span><span><?=max(0,$match['quantity_needed']-$match['received'])?> left</span></div><a class="button button-small" href="<?=e(url('donor/pledge.php?request='.$match['id']))?>">Pledge match →</a></article><?php endforeach;?></div><?php endif;?></div></div></section>
<?php require __DIR__ . '/../includes/footer.php'; ?>
